% Solver generated by SolverMapp
clear; clc;

%% Stage 0: Inputs and start values of state variables
mu_0       = 1e-3; % [Input] (Pa s) Viscosity at T_0
B          = 1800; % [Input] (K) Viscosity constant
T_0        = 293; % [Input] (K) Reference temperature
rho        = 998; % [Input] (kg/m^3) Density
u          = 2; % [Input] (m/s) Velocity
D          = 0.05; % [Input] (m) Diameter
T          = 313; % [Input] (K) Temperature
k_s        = 4.5e-5; % [Input] (m) Roughness
L          = 10; % [Input] (m) Length

%% Stage 1
% [FUNCTION] Viscosity: \mu(T) = \mu_0 \exp\left(\frac{B}{T} - \frac{B}{T_0}\right)
mu = @(T) mu_0 * exp(((B) / (T)) - ((B) / (T_0)));

%% Stage 2
% [EXPLICIT] Reynolds number: R_e = \frac{\rho u D}{\mu(T)}
R_e = ((rho * u * D) / (mu(T)));

%% Stage 3
% --- Switch: f by case ---
if R_e < 2300
    % [EXPLICIT] Laminar friction: f = \frac{64}{R_e}
    f = ((64) / (R_e));
else
    % [IMPLICIT] Colebrook: \frac{1}{\sqrt{f}} = -2 \log_{10}\left(\frac{k_s}{3.7 D} + \frac{2.51}{R_e \sqrt{f}}\right)
    % Newton–Raphson on the residual (left side - right side) = 0, solved for f
    % Branch: 1e-4 <= f
    res_f = @(f) ((1) / (sqrt(f))) - (-2 * log10(((k_s) / (3.7 * D)) + ((2.51) / (R_e * sqrt(f)))));
    f = 0.02; % initial guess
    f = max(f, 1e-4); % start on the branch
    converged = false;
    for it = 1:50
        h_nr = 1e-6 * max(abs(f), 1e-6);
        dr_nr = (res_f(f + h_nr) - res_f(f - h_nr)) / (2 * h_nr);
        if dr_nr == 0, warning('Zero derivative in the Newton iteration for f'); break; end
        f_new = f - res_f(f) / dr_nr;
        if f_new < 1e-4, f_new = 0.5 * (f + 1e-4); end % stay on the branch
        if abs(f_new - f) < 1e-12 * (1 + abs(f)), f = f_new; converged = true; break; end
        f = f_new;
    end
    if ~converged, warning('f did not converge in %d iterations', 50); end
end

%% Stage 4
% [EXPLICIT] Pressure drop: \Delta p = f \frac{L}{D} \frac{\rho u^2}{2}
Delta_p = f * ((L) / (D)) * ((rho * u^2) / (2));

%% Results
fprintf('%-12s = %s\n', 'mu_0', mat2str(mu_0));
fprintf('%-12s = %s\n', 'B', mat2str(B));
fprintf('%-12s = %s\n', 'T_0', mat2str(T_0));
fprintf('%-12s = %s\n', 'rho', mat2str(rho));
fprintf('%-12s = %s\n', 'u', mat2str(u));
fprintf('%-12s = %s\n', 'D', mat2str(D));
fprintf('%-12s = %s\n', 'T', mat2str(T));
fprintf('%-12s = %s\n', 'R_e', mat2str(R_e));
fprintf('%-12s = %s\n', 'f', mat2str(f));
fprintf('%-12s = %s\n', 'k_s', mat2str(k_s));
fprintf('%-12s = %s\n', 'L', mat2str(L));
fprintf('%-12s = %s\n', 'Delta_p', mat2str(Delta_p));